sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || !newValue) {
        return;
    }

    var state = g_form.getValue('state');

    if (!state) {
        return;
    }

    var ga = new GlideAjax('x_1523510_alloca_0.AllocateNowUtils');
    ga.addParam('sysparm_name', 'isDuplicateCityState');
    ga.addParam('sysparm_city', newValue);
    ga.addParam('sysparm_state', state);
    ga.addParam('sysparm_current_base', g_form.getUniqueValue());

    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            g_form.clearValue('city');

			g_form.addErrorMessage(
                'A base already exists in this city for the selected state.'
            );
        }
    });
}
